window.tam = (() => {
  const graph = window.__graph, model = graph.getModel();
  /** The cells of a library entry, as the sidebar makes them. */
  const cellsOf = (lib, title) => {
    let xml = TAMLIB[lib][title];
    if (!xml) throw new Error("no entry " + lib + "/" + title);
    if (xml.trim()[0] !== "<") xml = Graph.decompress(xml);
    const doc = mxUtils.parseXml(xml);
    const temp = new mxGraphModel();
    new mxCodec(doc).decode(doc.documentElement, temp);
    const layer = temp.getChildAt(temp.getRoot(), 0);
    return temp.getChildren(layer);
  };
  /** Drops a library entry at x, y as the sidebar's drop handler does; returns the top cells. */
  const insert = (lib, title, x, y) => {
    const cells = cellsOf(lib, title);
    model.beginUpdate();
    try {
      const bounds = graph.getBoundingBoxFromGeometry(cells, true);
      const dx = bounds ? x - bounds.x : x, dy = bounds ? y - bounds.y : y;
      return graph.importCells(cells, dx, dy, graph.getDefaultParent());
    } finally { model.endUpdate(); }
  };
  const vertex = (lib, title, x, y, label, size) => {
    const [cell] = insert(lib, title, x, y);
    if (size) graph.resizeCell(cell, new mxRectangle(x, y, size[0], size[1]));
    if (label !== undefined) graph.cellLabelChanged(cell, label, false);
    return cell;
  };
  /** An edge of the library, its ends dragged onto two shapes (floating, or at a fixed point). */
  const connect = (lib, title, from, to, label, fixed) => {
    const [edge] = insert(lib, title, 0, 0);
    model.beginUpdate();
    try {
      graph.connectCell(edge, from, true, fixed ? new mxConnectionConstraint(new mxPoint(fixed[0][0], fixed[0][1]), false) : null);
      graph.connectCell(edge, to, false, fixed ? new mxConnectionConstraint(new mxPoint(fixed[1][0], fixed[1][1]), false) : null);
      if (label !== undefined) graph.cellLabelChanged(edge, label, false);
    } finally { model.endUpdate(); }
    return edge;
  };
  const style = (cells, key, value) => graph.setCellStyles(key, value, cells);
  const toBack = (cells) => graph.orderCells(true, cells);
  const clear = () => { graph.selectAll(); graph.removeCells(graph.getSelectionCells(), true); };
  /** The page as draw.io saves it, uncompressed. */
  const file = (name) => {
    const node = new mxCodec(mxUtils.createXmlDocument()).encode(model);
    return '<mxfile host="app.diagrams.net"><diagram name="' + name + '" id="real">' + mxUtils.getXml(node) + "</diagram></mxfile>";
  };
  return { graph, model, cellsOf, insert, vertex, connect, style, toBack, clear, file };
})();
"ready";
